    worker_coord: WorkerCoordinator,
    driver_coord: DriverCoordinator,
    stats_coord: StatsCoordinator,
    inject_coord: InjectCoordinator,
}

struct IdleCoordinator {
    primary: AtomicUsize,
    secondary: AtomicUsize,
    tertiary: AtomicUsize,
    quaternary: AtomicUsize,
}

