    fn new() -> IdleCoordinator {
        IdleCoordinator {
            primary: AtomicUsize::new(0),
            secondary: AtomicUsize::new(0),
            tertiary: AtomicUsize::new(0),
            quaternary: AtomicUsize::new(0),
        }
    }
}

struct QueueCoordinator {
